function hydrateEmbeddedAssets() {
  document.documentElement.style.setProperty('--done-stamp-url', `url("${DONE_STAMP_DATA_URL}")`);
  document.documentElement.style.setProperty('--stop-stamp-url', `url("${STOP_STAMP_DATA_URL}")`);
  const logoEl = document.getElementById('mainBrandLogo');
  if (logoEl) logoEl.src = MAIN_LOGO_DATA_URL;
  const borrowedTitleEl = document.getElementById('homeBorrowedTitleImg');
  if (borrowedTitleEl && typeof BORROWED_BOOKS_TITLE_IMG === 'string') borrowedTitleEl.src = BORROWED_BOOKS_TITLE_IMG;
  const stackedCornerEl = document.getElementById('tabCornerStackedIcon');
  if (stackedCornerEl && typeof ILLUST_STACKED_BOOKS === 'string') stackedCornerEl.src = ILLUST_STACKED_BOOKS;
  document.querySelectorAll('img[data-icon]').forEach(img => {
    const key = img.getAttribute('data-icon');
    if (key && EMBEDDED_ICONS[key]) img.src = EMBEDDED_ICONS[key];
  });
}


