function renderLocalIcons(rootEl = document) {
  if (!rootEl || !rootEl.querySelectorAll) return;
  rootEl.querySelectorAll('i[data-lucide]').forEach(el => {
    const name = el.getAttribute('data-lucide');
    const inner = LOCAL_SVG_PATHS[name];
    if (!inner) { el.remove(); return; }
    const size = el.getAttribute('size') || '16';
    const color = el.getAttribute('color') || 'currentColor';
    const fill = el.getAttribute('fill') || 'none';
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('width', size);
    svg.setAttribute('height', size);
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('fill', fill);
    svg.setAttribute('stroke', color);
    svg.setAttribute('stroke-width', '2');
    svg.setAttribute('stroke-linecap', 'round');
    svg.setAttribute('stroke-linejoin', 'round');
    svg.setAttribute('aria-hidden', 'true');
    if (el.getAttribute('style')) svg.setAttribute('style', el.getAttribute('style'));
    svg.innerHTML = inner;
    el.replaceWith(svg);
  });
}

